<?php
declare(strict_types=1);
namespace Plati;
if(!defined('PLATI_ENTRY')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}
final class SiteFeed {
 static function eligibleSQL(string $alias='o'):string{return "NOT EXISTS(SELECT 1 FROM decisions site_gate WHERE site_gate.order_id=$alias.id AND site_gate.action='site_feed_excluded' AND site_gate.active=1)";}
 static function excluded(array $r):bool{$payment=label($r['_payment_status']??'');$delivery=label($r['_delivery_status']??'');$net=str_contains(label($r['payment_method']??''),'NETOPIA');if($delivery==='COMANDA ANULATA')return !($net&&$payment==='PLATA FINALIZATA');return $net&&in_array($payment,['PLATA ANULATA','TRANZACTIE INCOMPLETA (ANULATA DE SISTEM)','PLATA ESUATA'],true);}
 static function status(\PDO $db,array $r,?array $old,?array $actor):bool{if(!isset($r['_payment_status'])&&!isset($r['_delivery_status']))return false;$excluded=self::excluded($r);if($old){$prior=one($db,"SELECT * FROM decisions WHERE order_id=? AND action='site_feed_excluded' AND active=1",[$old['id']]);if($excluded&&!$prior)decision($db,'site_feed_excluded',['order'=>$old['id']],['payment_status'=>$r['_payment_status']??'','delivery_status'=>$r['_delivery_status']??''],'Comandă anulată fără plată NETOPIA finalizată sau tranzacție NETOPIA nefinalizată.',$actor,'site-gate:'.bin2hex(random_bytes(16)));elseif(!$excluded&&$prior){query($db,'UPDATE decisions SET active=0 WHERE id=?',[$prior['id']]);audit($db,'site_order_reactivated',['order'=>$r['id'],'previous_decision'=>$prior['id']],$actor);}}return $excluded;}
 static function download():array{$path=storage().'/site-feed-url.txt';$url=is_file($path)?trim((string)file_get_contents($path)):'';if(!preg_match('~^https://www\.goldendrinks\.ro/feed/orders/[a-f0-9]+$~D',$url))throw new Problem('Feed-ul SITE nu este configurat.',503);$context=stream_context_create(['http'=>['timeout'=>40,'follow_location'=>0,'header'=>"Accept: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\r\nUser-Agent: PlatiGoldendrinks/1.0\r\n"],'ssl'=>['verify_peer'=>true,'verify_peer_name'=>true]]);$in=@fopen($url,'rb',false,$context);if(!$in)throw new Problem('Feed-ul SITE nu poate fi descărcat momentan. Reîncearcă.',502);$dir=storage().'/uploads';if(!is_dir($dir))mkdir($dir,0700,true);$archive=$dir.'/site-feed-'.bin2hex(random_bytes(16)).'.xlsx';$out=fopen($archive,'wb');try{$bytes=stream_copy_to_stream($in,$out,40*1024*1024+1);$meta=stream_get_meta_data($in);if($bytes===false||$bytes===0||$bytes>40*1024*1024||($meta['timed_out']??false))throw new Problem('Descărcarea feed-ului este incompletă sau depășește 40 MB.',502);}catch(\Throwable $e){fclose($out);unlink($archive);throw $e;}finally{fclose($in);}fclose($out);try{$parsed=Sources::read($archive,'SITE-feed.xlsx','site');foreach(['Status plata','Status livrare'] as $h)if(!in_array($h,Sources::book($archive,'SITE-feed.xlsx')[0]['headers'],true))throw new Problem('Feed-ul SITE nu conține stările plății și livrării.');if($parsed['errors'])throw new Problem('Feed-ul SITE conține rânduri invalide. Nicio modificare aplicată.');return ['archive'=>$archive,'parsed'=>$parsed];}catch(\Throwable $e){unlink($archive);throw $e;}}
 static function import(\PDO $db,array $actor):array{permit($actor,'operate');$file=self::download();return Store::applyFiles($db,[$file],$actor);}
}
